// ⚙️ SETTINGS — this is the only node you need to edit.
// To add a source, add an item to the matching list. An empty list skips that source.
// Every list belongs to one report type (profile), and each profile has its own prompt:
//   investor  — investment analysis: claims, price levels, time frames, charts
//   newsfeed  — high-volume X news accounts, summarised per project (e.g. @aixbt_agent)
//   explainer — non-investment videos, detailed walkthrough of the argument
return [{
  json: {
    // investor: YouTube channels (@handle or a channel ID starting with UC)
    youtubeChannels: [
      'UCjFCzjkgSShdRZIVJx3SSlQ',
    ],
    // investor: X usernames (without the @)
    xAccounts: [
      'ChifoiCristian',
    ],
    // investor: newsletters, by the sender's email address (read from your Gmail account)
    emailSenders: [
      'newsletter@example.com',
    ],
    // newsfeed: X accounts that post dozens of short news items a day
    xNewsAccounts: [
      'aixbt_agent',
    ],
    // explainer: educational / self-development YouTube channels
    explainerChannels: [
      '@tizeslista_hu',
    ],

    // Local Whisper service (whisper-service/ in this repo) for videos without captions.
    // Leave empty to fall back to the video description instead.
    whisperUrl: 'http://host.docker.internal:8790',
    whisperLanguages: ['hu', 'en', 'ro'],  // preferred audio track languages

    // Frames from investor videos (YouTube, and videos attached to X posts), cut at
    // scene changes by the same local service, so the model sees the charts.
    // Needs whisperUrl. 0 turns it off.
    framesPerVideo: 10,
    maxFramesPerReport: 30,  // shared between the videos of one report (~1,200 tokens each)

    lookbackHours: 24,       // older content is skipped, even on the first run
    maxItemsPerSource: 5,    // max new items per source per run
    maxCharsPerItem: 40000,  // max characters per item sent to the LLM (≈ a 45-minute video)
    maxImages: 8,            // max X post images (charts) sent to the model per report

    model: 'claude-sonnet-5-5',
    // Optional: write the reports on a Claude subscription instead of an API key.
    // The local service (whisper-service/) runs the Claude Code CLI; usually the
    // same address as whisperUrl. Empty means the Anthropic API.
    claudeUrl: '',
    telegramChatId: '-100XXXXXXXXXX',  // default channel or chat ID
    // Optional: send a profile to its own chat. Empty means telegramChatId.
    telegramChatIds: {
      investor: '',
      newsfeed: '',
      explainer: '',
    },
  },
}];

// One output item per channel. Accepts both @handles and UC... channel IDs.
const cfg = $('⚙️ Settings').first().json;
const lists = [
  ['investor', cfg.youtubeChannels],
  ['explainer', cfg.explainerChannels],
];
const out = [];
for (const [profile, channels] of lists) {
  for (const raw of channels || []) {
    const c = String(raw).trim();
    if (!c) continue;
    out.push({
      json: {
        channel: c,
        profile,
        lookup: c.startsWith('UC')
          ? `id=${c}`
          : `forHandle=${encodeURIComponent(c.startsWith('@') ? c : '@' + c)}`,
      },
    });
  }
}
return out;

// Turn playlistItems responses into uniform content items within the lookback window.
const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const out = [];
$input.all().forEach((res, i) => {
  const profile = $('YouTube: channels').itemMatching(i)?.json.profile || 'investor';
  for (const it of res.json.items || []) {
    const s = it.snippet || {};
    const videoId = s.resourceId?.videoId;
    if (!videoId || Date.parse(s.publishedAt) < since) continue;
    out.push({
      json: {
        uid: `youtube:${videoId}`,
        source: 'youtube',
        profile,
        author: s.channelTitle || '',
        title: s.title || '',
        url: `https://www.youtube.com/watch?v=${videoId}`,
        published: new Date(s.publishedAt).toISOString(),
        text: s.description || '',
        videoId,
      },
    });
  }
});
return out;

// The transcript responses come back in the same order as the input videos.
// Videos without captions (or without a Supadata key) go on to the Whisper check.
const videos = $('YouTube: new videos only').all();
return $input.all().map((res, i) => {
  const video = videos[i].json;
  const transcript = typeof res.json.content === 'string' ? res.json.content.trim() : '';
  return {
    json: {
      ...video,
      text: transcript || video.text,
      hasTranscript: Boolean(transcript),
      transcriptSource: transcript ? 'youtube' : 'none',
      transcriptLanguage: transcript ? (res.json.lang || '') : '',
    },
  };
});

const cfg = $('⚙️ Settings').first().json;
const lists = [
  ['investor', cfg.xAccounts],
  ['newsfeed', cfg.xNewsAccounts],
];
const out = [];
for (const [profile, accounts] of lists) {
  for (const raw of accounts || []) {
    const userName = String(raw).trim().replace(/^@/, '');
    if (userName) out.push({ json: { userName, profile } });
  }
}
return out;

// twitterapi.io response → uniform items. Tweets live under "tweets" or "data.tweets"
// depending on the API version. Images (charts) are passed on as URLs.
const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const accounts = $('X: accounts').all();
const out = [];
$input.all().forEach((res, i) => {
  const payload = res.json || {};
  const tweets = payload.tweets || payload.data?.tweets || [];
  const user = accounts[i]?.json.userName || '';
  const profile = accounts[i]?.json.profile || 'investor';
  const limit = profile === 'newsfeed' ? tweets.length : cfg.maxItemsPerSource;
  for (const tw of tweets.slice(0, limit)) {
    const created = Date.parse(tw.createdAt);
    if (!(created >= since)) continue;
    const media = tw.extendedEntities?.media || tw.entities?.media || [];
    out.push({
      json: {
        uid: `x:${tw.id}`,
        source: 'x',
        profile,
        author: tw.author?.name ? `${tw.author.name} (@${user})` : `@${user}`,
        title: (tw.text || '').slice(0, 90).replace(/\n/g, ' '),
        url: tw.url || `https://x.com/${user}/status/${tw.id}`,
        published: new Date(created).toISOString(),
        text: tw.text || '',
        images: media.filter(m => m.type === 'photo').map(m => m.media_url_https),
        // The video is often in the quoted post (a reshared clip); the frames
        // service downloads it through this post's URL either way.
        hasVideo: [...media, ...(tw.quoted_tweet?.extendedEntities?.media || [])]
          .some(m => m.type === 'video' || m.type === 'animated_gif'),
      },
    });
  }
});
return out;

// Gmail search for the senders. With an empty list the newsletter branch is skipped.
const cfg = $('⚙️ Settings').first().json;
const senders = (cfg.emailSenders || []).map(s => String(s).trim()).filter(Boolean);
if (!senders.length) return [];
const days = Math.max(1, Math.ceil(cfg.lookbackHours / 24));
return [{ json: { q: `from:(${senders.join(' OR ')}) newer_than:${days}d` } }];

const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
return $input.all()
  .map(r => r.json)
  .filter(m => m.id && !m.error)
  .filter(m => !m.date || Date.parse(m.date) >= since)
  .map(m => {
    const from = m.from?.value?.[0] || {};
    return {
      json: {
        uid: `email:${m.id}`,
        source: 'email',
        profile: 'investor',
        author: from.name || from.address || m.from?.text || '',
        title: m.subject || '(no subject)',
        url: `https://mail.google.com/mail/u/0/#all/${m.id}`,
        published: new Date(m.date || Date.now()).toISOString(),
        text: (m.text || '').trim(),
      },
    };
  });

// One input item per report. Telegram allows at most 4096 characters per
// message, so each report is split at paragraph boundaries.
const reports = $('Build prompt').all();
const out = [];
$input.all().forEach((res, n) => {
  const { profile, chatId } = reports[n].json;
  const text = (res.json.content || [])
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('\n')
    .trim();
  if (!text) throw new Error(`Empty Claude response (${profile}): ` + JSON.stringify(res.json).slice(0, 500));

  const LIMIT = 3900;
  const chunks = [];
  let current = '';
  for (let para of text.split(/\n{2,}/)) {
    if (current.length + para.length + 2 > LIMIT && current.trim()) {
      chunks.push(current.trim());
      current = '';
    }
    while (para.length > LIMIT) {
      chunks.push(para.slice(0, LIMIT));
      para = para.slice(LIMIT);
    }
    current += para + '\n\n';
  }
  if (current.trim()) chunks.push(current.trim());

  chunks.forEach((chunk, i) => out.push({
    json: {
      chatId,
      chunk: chunks.length > 1 ? `${chunk}\n\n(${i + 1}/${chunks.length})` : chunk,
    },
  }));
});
return out;

// Whisper transcript in place of the description. If the service failed
// (not running, video too long, download blocked) the description stays.
return $input.all().map((res, i) => {
  const video = $('YouTube: needs Whisper?').itemMatching(i).json;
  const text = typeof res.json.text === 'string' ? res.json.text.trim() : '';
  return {
    json: {
      ...video,
      text: text || video.text,
      hasTranscript: Boolean(text),
      transcriptSource: text ? 'whisper' : 'none',
      transcriptLanguage: text ? (res.json.language || '') : '',
      whisperError: text ? undefined : (res.json.error?.message || res.json.error || 'no response'),
    },
  };
});

// Frames from the local service (base64 JPEGs with their timestamp). If the
// service failed (not running, download blocked, video too long) the item
// goes on without frames, and the report says so for YouTube videos.
return $input.all().map((res, i) => {
  const item = $('YouTube: needs frames?').itemMatching(i).json;
  const frames = Array.isArray(res.json.frames) ? res.json.frames : [];
  return {
    json: {
      ...item,
      frames,
      framesError: frames.length ? undefined
        : (res.json.error?.message || res.json.error || 'no frames'),
    },
  };
});

// Frames from the local service (base64 JPEGs with their timestamp). If the
// service failed (not running, download blocked, video too long) the item
// goes on without frames, and the report says so for YouTube videos.
return $input.all().map((res, i) => {
  const item = $('X: needs frames?').itemMatching(i).json;
  const frames = Array.isArray(res.json.frames) ? res.json.frames : [];
  return {
    json: {
      ...item,
      frames,
      framesError: frames.length ? undefined
        : (res.json.error?.message || res.json.error || 'no frames'),
    },
  };
});
